import csv
import json
def build_book(source, destination):
    totals = {}
    accepted = 0
    with open(source,newline="",encoding="utf-8") as handle:
        for row in csv.DictReader(handle):
            name = row["name"].strip()
            if name == "":
                continue
            try:
                score = int(row["score"])
            except ValueError:
                continue
            totals[name] = totals.get(name,0) + score
            accepted += 1
    result = {"totals":totals,"accepted":accepted}
    with open(destination,"w",encoding="utf-8") as handle:
        json.dump(result,handle,indent=2)
    return result
